-- Extend the single guarded canonical accommodation read with existing guardian relation.
CREATE OR REPLACE FUNCTION public.get_conference_accommodation(p_device uuid, p_conference uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare context jsonb;result jsonb;
begin
 context:=platform_private.require_conference_accommodation_context(p_device,p_conference,'conference.accommodation.view',false);
 select coalesce(jsonb_agg(jsonb_build_object('assignmentId',a.id,'assignmentRevision',a.revision,'houseId',h.id,'name',h.name,'description',h.description,'position',h.position,'revision',h.revision,'floors',(select coalesce(jsonb_agg(jsonb_build_object('floorId',f.id,'name',f.name,'position',f.position,'revision',f.revision,'rooms',(select coalesce(jsonb_agg(jsonb_build_object('roomAssignmentId',ra.id,'roomAssignmentRevision',ra.revision,'keyHolderOccupancyId',case when exists(select 1 from public.conference_accommodation_occupancies ko where ko.id=ra.key_holder_occupancy_id and ko.room_id=ra.room_id and ko.conference_id=ra.conference_id and ko.arrival_day<=platform_private.conference_operational_day(ra.conference_id) and coalesce(ko.leave_day,platform_private.conference_accommodation_duration(ra.conference_id)+1)>platform_private.conference_operational_day(ra.conference_id)) then ra.key_holder_occupancy_id else null end,'keyHolderPersonId',(select p.person_id from public.conference_accommodation_occupancies ko join public.conference_participations p on p.id=ko.participation_id where ko.id=ra.key_holder_occupancy_id and ko.room_id=ra.room_id),'keyHolderName',(select pe.full_name from public.conference_accommodation_occupancies ko join public.conference_participations p on p.id=ko.participation_id join platform.people pe on pe.id=p.person_id where ko.id=ra.key_holder_occupancy_id and ko.room_id=ra.room_id),'keyDeliveredAt',ra.key_delivered_at,'keyDeliveredBy',ra.key_delivered_by,'roomId',r.id,'roomNumber',r.room_number,'baseCapacity',r.base_capacity,'extraBedCapacity',r.extra_bed_capacity,'notes',r.notes,'isClosed',r.is_closed,'closedDay',r.closed_day,'position',r.position,'revision',r.revision,'occupancies',(select coalesce(jsonb_agg(jsonb_build_object('occupancyId',o.id,'revision',o.revision,'arrivedAt',o.arrived_at,'arrivedBy',o.arrived_by,'arrivalDay',o.arrival_day,'leaveDay',o.leave_day,'bedType',o.bed_type,'extraBedPersonType',o.extra_bed_person_type,'participationId',p.id,'participationStatus',p.status,'guardianParticipationId',p.guardian_participation_id,'guardianPersonId',gp.person_id,'guardianFullName',gpe.full_name,'guardianParticipationStatus',gp.status,'person',jsonb_build_object('personId',pe.id,'fullName',pe.full_name,'phone',pe.phone,'gender',pe.gender,'dateOfBirth',pe.date_of_birth,'church',pe.church)) order by pe.full_name,o.id),'[]') from public.conference_accommodation_occupancies o join public.conference_participations p on p.id=o.participation_id join platform.people pe on pe.id=p.person_id left join public.conference_participations gp on gp.id=p.guardian_participation_id and gp.conference_id=p.conference_id left join platform.people gpe on gpe.id=gp.person_id where o.room_id=r.id and o.conference_id=p_conference)) order by r.position,r.id),'[]') from public.conference_room_assignments ra join public.conference_accommodation_rooms r on r.id=ra.room_id where ra.conference_id=p_conference and ra.house_id=h.id and r.floor_id=f.id)) order by f.position,f.id),'[]') from public.conference_accommodation_floors f where f.house_id=h.id and exists(select 1 from public.conference_room_assignments ra where ra.conference_id=p_conference and ra.house_id=h.id and ra.room_id in(select rr.id from public.conference_accommodation_rooms rr where rr.floor_id=f.id)))) order by h.position,h.id),'[]') into result from public.conference_house_assignments a join public.conference_accommodation_houses h on h.id=a.house_id where a.conference_id=p_conference and exists(select 1 from public.conference_room_assignments ra where ra.conference_id=p_conference and ra.house_id=h.id);
 return jsonb_build_object('conferenceId',p_conference,'houses',result,'pricing',platform_private.conference_accommodation_pricing_projection(p_conference));
end $function$
;
